<script setup>
import{ref,onMounted}from'vue';import{api}from'../services/api.js';import UiState from'./UiState.vue';import BaseModal from'./BaseModal.vue'
const data=ref({years:[],rows:[],annual:{}}),loading=ref(true),error=ref(''),search=ref(''),detail=ref(null),detailRows=ref([]),detailLoading=ref(false),detailError=ref('')
const quantity=value=>new Intl.NumberFormat('ca-ES',{maximumFractionDigits:4}).format(Number(value||0))
const money=value=>new Intl.NumberFormat('ca-ES',{style:'currency',currency:'EUR'}).format(Number(value||0))
const date=value=>value?new Intl.DateTimeFormat('ca-ES',{dateStyle:'short'}).format(new Date(value)):'—'
const dateTime=value=>value?new Intl.DateTimeFormat('ca-ES',{dateStyle:'short',timeStyle:'short'}).format(new Date(value)):'—'
const compostPercentage=year=>{const compost=Number(data.value.annual[year]?.compost||0),rest=Number(data.value.annual[year]?.rest||0),total=compost+rest;return new Intl.NumberFormat('ca-ES',{minimumFractionDigits:2,maximumFractionDigits:2}).format(total?compost/total*100:0)+' %'}
async function load(){loading.value=true;error.value='';try{data.value=await api.get('/sales/articles')}catch(e){error.value=e.message}finally{loading.value=false}}
const visible=()=>data.value.rows.filter(row=>!search.value||row.articleCode.toLowerCase().includes(search.value.toLowerCase())||row.articleName.toLowerCase().includes(search.value.toLowerCase()))
async function openDetail(row,year){if(row.quantities[year]==null)return;detail.value={row,year};detailRows.value=[];detailError.value='';detailLoading.value=true;try{detailRows.value=await api.get(`/sales/articles/${encodeURIComponent(row.articleCode)}/lines?year=${year}&product_name=${encodeURIComponent(row.articleName)}`)}catch(e){detailError.value=e.message}finally{detailLoading.value=false}}
const warnings=row=>{if(!row.warnings)return'Cap';if(Array.isArray(row.warnings))return row.warnings.join(' · ');try{return JSON.parse(row.warnings).join(' · ')}catch{return String(row.warnings)}}
onMounted(load)
</script>
<template><div class="toolbar"><label class="search article-table-search"><span class="sr-only">Cercar article</span><input v-model="search" type="search" placeholder="Cercar per codi o nom d’article"></label><button class="button secondary" @click="load">Actualitzar</button></div><UiState :loading="loading" :error="error" :empty="!data.rows.length" empty-text="No hi ha vendes confirmades per mostrar."><section class="annual-summary"><article v-for="year in data.years" :key="year" class="card annual-card"><h3>{{year}}</h3><div><span>Compost</span><strong>{{quantity(data.annual[year]?.compost)}} t · {{money(data.annual[year]?.compostAmount)}}</strong></div><div><span>Resta d’articles</span><strong>{{quantity(data.annual[year]?.rest)}} t · {{money(data.annual[year]?.restAmount)}}</strong></div><div class="percentage-row"><span>% compost</span><strong>{{compostPercentage(year)}}</strong></div></article></section><div class="table-wrap"><table class="article-matrix"><thead><tr><th>Article</th><th v-for="year in data.years" :key="year">{{year}}</th></tr></thead><tbody><tr v-for="row in visible()" :key="`${row.articleCode}:${row.articleName}`" :class="{'compost-row':row.articleCode==='__COMPOST__'}"><td data-label="Article"><strong>{{row.articleName}}</strong><small v-if="row.articleCode!=='__COMPOST__'">{{row.articleCode}}</small></td><td v-for="year in data.years" :key="year" :data-label="String(year)"><button v-if="row.quantities[year]!=null" class="cell-detail-button" :aria-label="`Veure línies de ${row.articleName} de ${year}`" @click="openDetail(row,year)"><span class="article-year-values"><strong>{{quantity(row.quantities[year])}} t</strong><span>{{money(row.amounts?.[year])}}</span></span></button><span v-else>—</span></td></tr></tbody></table></div></UiState>
<BaseModal :open="!!detail" size="large" :title="detail?`${detail.row.articleName} · ${detail.year}`:''" @close="detail=null"><div class="detail-summary"><span><strong>{{detailRows.length}}</strong> línies</span><span>t: <strong>{{quantity(detailRows.reduce((sum,row)=>sum+Number(row.quantity||0),0))}}</strong></span><span>Total: <strong>{{money(detailRows.reduce((sum,row)=>sum+Number(row.total_amount||0),0))}}</strong></span></div><UiState :loading="detailLoading" :error="detailError" :empty="!detailRows.length" empty-text="No s’han trobat línies."><div class="table-wrap detail-lines-wrap"><table class="detail-lines-table"><thead><tr><th>Data</th><th class="detail-client-column">Client</th><th>Albarà</th><th>Article i concepte</th><th>Matrícula</th><th>Remolc</th><th>t</th><th>Preu</th><th>Base</th></tr></thead><tbody><tr v-for="row in detailRows" :key="row.id"><td>{{date(row.delivery_date)}}</td><td class="detail-client-column"><strong>{{row.client_name}}</strong><small>{{row.client_code}}</small></td><td>{{row.delivery_note_number}}</td><td><strong>{{row.product_code}}</strong><div>{{row.concept}}</div></td><td>{{row.vehicle_plate||'—'}}<small v-if="row.vehicle_plate_normalized">{{row.vehicle_plate_normalized}}</small></td><td>{{row.trailer_plate||'—'}}</td><td class="number">{{quantity(row.quantity)}}</td><td class="number">{{money(row.unit_price)}}</td><td class="number">{{money(row.taxable_base)}}</td></tr></tbody></table></div></UiState><template #actions><button class="button secondary" @click="detail=null">Tancar</button></template></BaseModal></template>

<style scoped>
.article-year-values{display:flex;flex-direction:column;gap:4px;align-items:flex-end}
</style>
